    /// &#32;    <span class="comment">// be known already</span>
    /// &#32;    <span class="keyword">if</span> (dirEntry<span class="operator">.</span>fileInfo()<span class="operator">.</span>fileName()<span class="operator">.</span>endsWith(u<span class="string">".conf"</span>)) { <span class="comment">/* ... */</span> }
    ///  }
