    /// &#32;    <span class="comment">// ...</span>
    ///  } <span class="keyword">catch</span> (<span class="keyword">const</span> <span class="type"><a href="http://doc.qt.io/qt-5/qunhandledexception.html" translate="no">QUnhandledException</a></span> <span class="operator">&amp;</span>e) {
